-- ===== prisma/manual/001_constraints_and_triggers.sql =====
-- Database-level guarantees Prisma cannot express. Apply once, inside the first migration
-- (see README: "Initial migration"). These make the key money/audit rules unbreakable even if
-- application code has a bug.

-- Star balances can never go negative.
ALTER TABLE "StarAccount" ADD CONSTRAINT star_balance_non_negative CHECK ("balance" >= 0);

-- Ledger rows must change something.
ALTER TABLE "StarLedgerEntry" ADD CONSTRAINT star_ledger_amount_non_zero CHECK ("amount" <> 0);

-- Append-only tables: any UPDATE or DELETE is rejected.
CREATE OR REPLACE FUNCTION saqr_forbid_mutation() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'Table "%" is append-only', TG_TABLE_NAME USING ERRCODE = '55000';
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER star_ledger_append_only BEFORE UPDATE OR DELETE ON "StarLedgerEntry"
  FOR EACH ROW EXECUTE FUNCTION saqr_forbid_mutation();

CREATE TRIGGER order_event_append_only BEFORE UPDATE OR DELETE ON "OrderEvent"
  FOR EACH ROW EXECUTE FUNCTION saqr_forbid_mutation();

CREATE TRIGGER audit_log_append_only BEFORE UPDATE OR DELETE ON "AuditLog"
  FOR EACH ROW EXECUTE FUNCTION saqr_forbid_mutation();

-- ===== prisma/manual/002_phase2_append_only.sql =====
-- Phase 2: history tables are append-only. A change is a NEW row with a new effective date;
-- old rows can never be edited or deleted, so past calculations can never be rewritten.
-- Requires saqr_forbid_mutation() from 001_constraints_and_triggers.sql.

CREATE TRIGGER platform_setting_version_append_only BEFORE UPDATE OR DELETE ON "PlatformSettingVersion"
  FOR EACH ROW EXECUTE FUNCTION saqr_forbid_mutation();

CREATE TRIGGER commission_rate_append_only BEFORE UPDATE OR DELETE ON "CommissionRate"
  FOR EACH ROW EXECUTE FUNCTION saqr_forbid_mutation();

CREATE TRIGGER delivery_fee_version_append_only BEFORE UPDATE OR DELETE ON "DeliveryFeeVersion"
  FOR EACH ROW EXECUTE FUNCTION saqr_forbid_mutation();

-- Sanity bounds enforced by the database as a last line of defense.
ALTER TABLE "CommissionRate" ADD CONSTRAINT commission_rate_range CHECK ("basisPoints" >= 0 AND "basisPoints" <= 5000);
ALTER TABLE "DeliveryFeeVersion" ADD CONSTRAINT delivery_fee_range CHECK ("feeCents" >= 0 AND "feeCents" <= 100000);

-- ===== prisma/manual/003_phase3_catalog.sql =====
-- Phase 3: database-level guards for the catalog. Apply once (after 001 and 002).

-- A product price is a positive number of piasters, capped at 100,000 EGP.
ALTER TABLE "Product" ADD CONSTRAINT product_price_range CHECK ("priceCents" >= 1 AND "priceCents" <= 10000000);

-- ===== prisma/manual/004_phase4_parent_orders.sql =====
-- Phase 4: paste at the end of the generated phase4 migration.sql (see README). NOT yet run against a database.
ALTER TABLE "ParentOrder" ADD CONSTRAINT parent_order_money_non_negative
  CHECK ("subtotalCents" >= 0 AND "deliveryFeeCents" >= 0 AND "totalCents" = "subtotalCents" + "deliveryFeeCents");

-- Suborder money must add up and never be negative.
ALTER TABLE "Order" ADD CONSTRAINT order_money_consistent
  CHECK ("subtotalCents" >= 0 AND "deliveryFeeCents" >= 0 AND "totalCents" = "subtotalCents" - "discountCents" + "deliveryFeeCents");
ALTER TABLE "OrderItem" ADD CONSTRAINT order_item_quantity_positive CHECK ("quantity" >= 1 AND "unitPriceCents" >= 0);
ALTER TABLE "Payment" ADD CONSTRAINT payment_amount_positive CHECK ("amountCents" > 0);
ALTER TABLE "Refund" ADD CONSTRAINT refund_amount_positive CHECK ("amountCents" > 0);

-- Only ONE confirmed payment may use the same method + transfer reference (blocks double-confirming a transfer).
CREATE UNIQUE INDEX payment_confirmed_reference_unique ON "Payment" ("method", "referenceNo")
  WHERE "confirmedAt" IS NOT NULL AND "referenceNo" IS NOT NULL;

-- ===== prisma/manual/005_phase5_plans.sql =====
-- Plans: apply at the end of the generated migration. Run in CI after 004.
-- One pending purchase per user at a time (stops spam and double submission races).
CREATE UNIQUE INDEX plan_purchase_one_pending_per_user ON "PlanPurchase" ("userId") WHERE "status" = 'PENDING';
-- Only one approved purchase per transfer reference.
CREATE UNIQUE INDEX plan_purchase_approved_reference_unique ON "PlanPurchase" ("method", "referenceNo") WHERE "status" = 'APPROVED';
ALTER TABLE "Plan" ADD CONSTRAINT plan_values_sane CHECK ("priceCents" > 0 AND "baseStars" >= 0 AND "bonusStars" >= 0 AND ("offerQuota" IS NULL OR "offerQuota" >= 0));
ALTER TABLE "PlanPurchase" ADD CONSTRAINT plan_purchase_values_sane CHECK ("priceCentsSnap" > 0 AND "baseStarsSnap" >= 0 AND "bonusStarsSnap" >= 0);

-- ===== prisma/manual/006_memberships_settlements.sql =====
-- Merchant memberships and commission settlements. Apply after 005.

-- One pending membership purchase per shop at a time; one approved purchase per transfer reference.
CREATE UNIQUE INDEX membership_purchase_one_pending_per_shop ON "MembershipPurchase" ("merchantId") WHERE "status" = 'PENDING';
CREATE UNIQUE INDEX membership_purchase_approved_reference_unique ON "MembershipPurchase" ("method", "referenceNo") WHERE "status" = 'APPROVED';
ALTER TABLE "MembershipPlan" ADD CONSTRAINT membership_plan_values_sane CHECK ("priceCents" > 0 AND "durationDays" BETWEEN 1 AND 366);
ALTER TABLE "MembershipPurchase" ADD CONSTRAINT membership_purchase_values_sane CHECK ("priceCentsSnap" > 0 AND "durationDaysSnap" BETWEEN 1 AND 366);

-- Settlement arithmetic must always add up, whatever the application does.
ALTER TABLE "CommissionSettlement" ADD CONSTRAINT settlement_totals_consistent
  CHECK ("orderCount" >= 0 AND "baseCents" >= 0 AND "commissionCents" >= 0 AND "adjustmentCents" <= 0 AND "netDueCents" = "commissionCents" + "adjustmentCents");
ALTER TABLE "CommissionSettlement" ADD CONSTRAINT settlement_month_key_format CHECK ("monthKey" ~ '^[0-9]{4}-(0[1-9]|1[0-2])$');
ALTER TABLE "CommissionSettlement" ADD CONSTRAINT settlement_paid_has_details
  CHECK (("status" = 'ISSUED' AND "paidAt" IS NULL) OR ("status" = 'PAID' AND "paidAt" IS NOT NULL AND "paymentReference" IS NOT NULL));
ALTER TABLE "CommissionSettlementLine" ADD CONSTRAINT settlement_line_sign
  CHECK (("kind" = 'ORDER' AND "commissionCents" >= 0 AND "baseCents" >= 0) OR ("kind" = 'ADJUSTMENT' AND "commissionCents" < 0));

-- Lines are append-only. Statements can never be deleted and their figures can never change; only the payment columns move.
CREATE TRIGGER settlement_line_append_only BEFORE UPDATE OR DELETE ON "CommissionSettlementLine"
  FOR EACH ROW EXECUTE FUNCTION saqr_forbid_mutation();

CREATE OR REPLACE FUNCTION saqr_settlement_guard() RETURNS trigger AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Settlements cannot be deleted' USING ERRCODE = '55000';
  END IF;
  IF NEW."merchantId" IS DISTINCT FROM OLD."merchantId" OR NEW."monthKey" IS DISTINCT FROM OLD."monthKey"
     OR NEW."periodStart" IS DISTINCT FROM OLD."periodStart" OR NEW."periodEnd" IS DISTINCT FROM OLD."periodEnd"
     OR NEW."orderCount" IS DISTINCT FROM OLD."orderCount" OR NEW."baseCents" IS DISTINCT FROM OLD."baseCents"
     OR NEW."commissionCents" IS DISTINCT FROM OLD."commissionCents" OR NEW."adjustmentCents" IS DISTINCT FROM OLD."adjustmentCents"
     OR NEW."netDueCents" IS DISTINCT FROM OLD."netDueCents" OR NEW."issuedAt" IS DISTINCT FROM OLD."issuedAt" THEN
    RAISE EXCEPTION 'Settlement figures are frozen' USING ERRCODE = '55000';
  END IF;
  IF OLD."status" = 'PAID' AND (NEW."status" IS DISTINCT FROM OLD."status" OR NEW."paidAt" IS DISTINCT FROM OLD."paidAt" OR NEW."paymentReference" IS DISTINCT FROM OLD."paymentReference") THEN
    RAISE EXCEPTION 'A paid settlement cannot be changed' USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER settlement_guard BEFORE UPDATE OR DELETE ON "CommissionSettlement"
  FOR EACH ROW EXECUTE FUNCTION saqr_settlement_guard();
